def ref_parse_loose(s: str) -> int:
    total = 0
    prev = 0
    for ch in reversed(s):
        v = _REF_VALUES[ch]
        if v < prev:
            total -= v
        else:
            total += v
            prev = v
    return total

def ref_from_roman(s: str) -> int:
    # strict: accept iff s == ref_to_roman(n) for some 1..3999
    if not isinstance(s, str):
        raise TypeError
    if s == "":
        raise ValueError
    for ch in s:
        if ch not in _REF_VALUES:
            raise ValueError(f"bad char {ch!r}")
    n = ref_parse_loose(s)
    if not 1 <= n <= 3999:
        raise ValueError
    if ref_to_roman(n) != s:
        raise ValueError
    return n

@given(st.integers(min_value=1, max_value=3999))
def test_from_roman_accepts_every_canonical_string(n):
    s = ref_to_roman(n)
    assert from_roman(s) == n
